using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class StairACollarCleanup {public static object Run(){var scene=SceneManager.GetActiveScene();if(scene.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=scene.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var reports=new List<object>();foreach(var mf in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>AssetDatabase.GetAssetPath(f.sharedMesh).EndsWith("AF_B5_PortalCollars.fbx"))){var source=mf.sharedMesh;var vs=source.vertices;var m=UnityEngine.Object.Instantiate(source);m.name="TA_PortalCollars_VAReplaced";int removed=0;float maxRadius=0;for(int sub=0;sub<m.subMeshCount;sub++){var ts=source.GetTriangles(sub);var keep=new List<int>();for(int i=0;i<ts.Length;i+=3){var a=mf.transform.TransformPoint(vs[ts[i]]);var b=mf.transform.TransformPoint(vs[ts[i+1]]);var c=mf.transform.TransformPoint(vs[ts[i+2]]);var center=(a+b+c)/3;float distance=Vector2.Distance(new Vector2(center.x,center.z),new Vector2(-44,28));if(distance<7){removed++;maxRadius=Mathf.Max(maxRadius,new[]{a,b,c}.Max(p=>Vector2.Distance(new Vector2(p.x,p.z),new Vector2(-44,28))));}else keep.AddRange(new[]{ts[i],ts[i+1],ts[i+2]});}m.SetTriangles(keep,sub);}if(removed==0){UnityEngine.Object.DestroyImmediate(m);continue;}if(maxRadius>7.2f)throw new Exception("Collar removal outside VA scope");m.RecalculateBounds();m.UploadMeshData(false);string path="Assets/Afrer_Seconds/05.Model/Environment/B5/"+m.name+".asset";if(AssetDatabase.LoadAssetAtPath<Mesh>(path))throw new Exception("Override already exists; inspect before replacing");AssetDatabase.CreateAsset(m,path);mf.sharedMesh=m;foreach(var col in mf.GetComponents<MeshCollider>())if(col.sharedMesh==source)col.sharedMesh=m;reports.Add(new{objectName=mf.name,removedTriangles=removed,maxRadius,retainedTriangles=m.triangles.Length/3});}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));File.WriteAllText(repo+"/Docs/검수/2026-11-08_T02_StairA/collar_cleanup.json",JsonConvert.SerializeObject(reports,Formatting.Indented));return reports;}}
